query:
DELETE FROM investments
WHERE id IN (
  SELECT id FROM (
    SELECT id,
      ROW_NUMBER() OVER (
        PARTITION BY company_name, announcement_date, target_country_name 
        ORDER BY id
      ) as rn
    FROM investments
  ) as ranked
  WHERE rn > 1
);

